mapper.select:
SELECT id, user_id, product_id, rating, comment FROM t_comment WHERE product_id = #{productId}
ORDER BY rating DESC, id DESC ORDER BY rating ASC, id DESC ORDER BY id DESC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*)
FROM t_comment
WHERE product_id = #{productId}

